class Solution:
    def isPossibleToSplit(self, nums: List[int]) -> bool:
        from collections import Counter
        
        # Count frequency of each element
        freq = Counter(nums)
        
        # If any element appears more than twice, we can't split it
        # into two distinct arrays (each array can have at most one copy)
        for count in freq.values():
            if count > 2:
                return False
        
        return True
